-- 1. 구글시트 연동 테이블
create table if not exists public."IT_AS" (
  "id" bigint generated by default as identity primary key,
  "순" text, "접수일" text, "월" text, "접수" text, "처리여부" text,
  "유입경로" text, "접수자" text, "처리자" text, "순2" text, "등급" text,
  "미수" text, "임대여부" text, "남은개월" text, "지역" text, "상호" text,
  "연락처" text, "자산번호" text, "기종" text, "시리얼번호" text, "증상" text,
  "처리내용" text, "비고" text, "특이사항" text, "일반전화" text, "확장성" text,
  "품목" text, "제조사" text, "기본금액" text, "연평균" text, "계약일" text,
  "종료일" text, "교체일" text, "주소" text, "기기상태" text, "시/도" text,
  "시/구" text, "방문주기" text, "납품담당" text, "키맨" text, "추가조건" text,
  "장비소유주" text, "위탁/유지보수및기타사항" text
);

create unique index if not exists "IT_AS_순_unique" on public."IT_AS" ("순");

alter table public."IT_AS" enable row level security;

grant usage on schema public to anon;
grant select, insert, update on table public."IT_AS" to anon;
grant usage, select on all sequences in schema public to anon;

drop policy if exists "IT_AS_select" on public."IT_AS";
drop policy if exists "IT_AS_insert" on public."IT_AS";
drop policy if exists "IT_AS_update" on public."IT_AS";

create policy "IT_AS_select" on public."IT_AS" for select to anon using (true);
create policy "IT_AS_insert" on public."IT_AS" for insert to anon with check (true);
create policy "IT_AS_update" on public."IT_AS" for update to anon using (true) with check (true);

-- 2. 업무분장 테이블 (앱에서 입력·수정·완료)
create table if not exists public."IT_AS_WORK" (
  id bigint generated by default as identity primary key,
  as_no text,
  work_date date not null default current_date,
  start_time text,
  end_time text,
  status text not null default '예정' check (status in ('예정','진행중','완료')),
  category text,
  work_type text,
  grade text,
  company text,
  assignee text,
  summary text,
  checklist jsonb not null default '[]'::jsonb,
  work_minutes integer,
  bottleneck text,
  completed_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create index if not exists it_as_work_date_idx on public."IT_AS_WORK" (work_date);
create index if not exists it_as_work_status_idx on public."IT_AS_WORK" (status);

alter table public."IT_AS_WORK" enable row level security;

grant select, insert, update on table public."IT_AS_WORK" to anon;
grant usage, select on all sequences in schema public to anon;

drop policy if exists it_as_work_select on public."IT_AS_WORK";
drop policy if exists it_as_work_insert on public."IT_AS_WORK";
drop policy if exists it_as_work_update on public."IT_AS_WORK";

create policy it_as_work_select on public."IT_AS_WORK" for select to anon using (true);
create policy it_as_work_insert on public."IT_AS_WORK" for insert to anon with check (true);
create policy it_as_work_update on public."IT_AS_WORK" for update to anon using (true) with check (true);
